import json

# Parse each section from the output
def extract_json_section(text, label):
    marker = f'{label}: '
    start = text.find(marker)
    if start == -1:
        return None
    start += len(marker)
    # Find the start of the next section or end
    next_markers = ['ORDER: ', 'ITEMS: ', 'PAYMENTS: ', 'FULFILLMENTS: ']
    ends = []
    for m in next_markers:
        if m != marker:
            idx = text.find('\n' + m, start)
            if idx != -1:
                ends.append(idx)
    venv_idx = text.find('\n(.venv)', start)
    if venv_idx != -1:
        ends.append(venv_idx)
    end = min(ends) if ends else len(text)
    return json.loads(text[start:end].strip())

